#!/usr/bin/env python3
"""Generate docs/higuruma/SPRITE_MAP.md from docs/higuruma/source_rects.json + higurumaSprites.js + higurumaData.js TIMELINE."""
import json, re, subprocess, os
ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
R = json.load(open(f'{ROOT}/docs/higuruma/source_rects.json'))
anim = json.loads(subprocess.check_output(['node', '-e', "import('./higurumaSprites.js').then(m=>import('./higurumaData.js').then(d=>console.log(JSON.stringify({a:m.HIGURUMA_ANIM,t:d.TIMELINE}))))"], cwd=ROOT))
A, T = anim['a'], anim['t']
USE = {
 'idle': 'Neutral stance (loop)', 'walk': 'Walk forward (run cycle at walk speed)', 'walk_back': 'Walk back (crouched step; UNCERTAIN purpose in the sheet)',
 'run': 'Run', 'dash': 'Ordinary shared dash + Precedent dash', 'turn': 'Grounded facing change (front-facing cell)', 'jump': 'Jump rise',
 'doubleJump': 'Shared double jump (tuck → rise)', 'fall': 'Fall', 'land': 'Landing after a genuine landing', 'crouch': 'Crouch', 'guard': 'Guard',
 'hurt': 'Hitstun', 'knockdown': 'Knockdown', 'lose': 'Defeat pose', 'win': 'Victory: back turned, gavel dissolves', 'intro': 'Match intro: turn + gavel manifests',
 'introSettle': 'Intro settle (lean → idle)', 'light': 'Gavel Chop (small gavel J1)', 'hJ2': 'Gavel Straight (J2)', 'hJ3': 'Spinning Close (J3, low spinning sweep)',
 'hLow': 'Low Gavel Check', 'hPoke': 'Extended Lash (corded gavel, tethered — not a throw)', 'up': 'Rising Gavel launcher', 'air': 'Rising Air Swing',
 'heavy': 'Giant Gavel Overhead', 'hSweep': 'Giant Gavel Upswing', 'hExt': 'Extension of the Court (long-handle extension)',
 'hCross': 'Cross-Examination (crouched advance → 3 strikes)', 'hRise': 'Rising Objection (scoop → spin → leaping overhead → land)',
 'hOrder': 'Order in the Court (giant gavel raise → leap → slam)', 'hObj': 'Objection stance', 'hObjHit': 'Objection counter strike',
 'ultOpen': 'Deadly Sentencing opener (extended gavel)', 'ultCase': 'CASE REVIEW: gavel vanishes, evidence presented', 'ultConfiscate': 'CONFISCATION beat (gavel flash → vanish)',
 'ultVerdict': 'VERDICT: giant gavel overhead + slam', 'ultSword': "Executioner's Sword: manifest, raise, thrust, dive lunge", 'ultSettle': 'Cinematic exit (evidence returns → idle)'}
cells = R['cells']; used = set(c for v in R['actions'].values() for c in v)
L = ['# Hiromi Higuruma — sprite map', '',
 f"Source: `higuruma_hiromi_sprites_sheet_manga__by_mugengojoplayer_dm448a4.png` (supplied; caption \"Sprite Sheet By Mugen Matias\") — SHA-256 `{R['sha256']}`.",
 f"Background key: exact RGB{tuple(R['key'])} only; the sprite area holds no other green. The caption text and the sheet's large portrait are excluded from gameplay frames;",
 f"the portrait rect {R['portrait']['rect']} is keyed and cropped (text tail removed) to `assets/higuruma/portrait_full.png` / `portrait.png` (HUD, select, cut-in).", '',
 f"Every cell is pasted into one symmetric **{R['cell']['w']}×{R['cell']['h']}** frame with the anchor (hair-top centre x, lowest body pixel y; airborne cells use the band floor) at",
 f"**({R['cell']['ox']}, {R['cell']['oy']})** = the cell centre, so a mirrored (left-facing) frame stays on its hurtbox. Nearest-neighbour only; pixels are never redrawn,",
 'nothing is generated, no other character art is used.', '',
 f"Coverage: **{len(cells)} cells extracted from 15 bands, unused cells: {len([c for c in cells if c not in used])}**.", '',
 'Generated by `tools/higuruma/sprite_map_md.py` (extractor `tools/higuruma/extract.py`; rects `docs/higuruma/source_rects.json`; contact sheet `docs/higuruma/contact_sheet.png`).', '',
 '## Bands', '',
 '| band | cells | reading of the supplied art | used for |', '|---|---|---|---|',
 '| b00 | 3 | standing idle | idle, introSettle |', '| b01 | 9 | run start + 8-cell run cycle | run, walk, dash |',
 '| b02 | 6 | 0–1 crouched step (purpose UNCERTAIN) · 2 front-facing · 3 tuck · 4–5 horizontal lunge | walk_back, turn, doubleJump, dash |',
 '| b03 | 3 | crouch / landing | crouch, land |', '| b04 | 2 | hurt | hurt |', '| b05 | 3 | jump | jump, fall, doubleJump |', '| b06 | 1 | braced stance | guard, hObj |',
 '| b07 | 7 | knocked down | knockdown, lose |', '| b08 | 12 | 0–5 back turned, gavel dissolves · 6–9 turn + gavel manifests · 10–11 lean | win, intro, introSettle |',
 '| b09 | 13 | 0–4 low gavel check · 5–9 chop / jab / retract · 10–12 gavel flash → vanish | hLow, light, hJ2, hObjHit, ultConfiscate |',
 '| b10 | 14 | 0–7 scoop → spin → leaping overhead swing → land (5–6 airborne swing) · 8–13 standing rising launcher | hRise, air, up |',
 '| b11 | 12 | 0–5 crouched advance, gavel trailing · 6–11 spinning low sweep | hCross, hJ3 |',
 '| b12 | 12 | gavel vanishes → glowing evidence presented → returns | ultCase, ultSettle |',
 '| b13 | 10 | GIANT gavel: 0–3 overhead · 4 raise · 5 leap · 6 slam with dust · 7 hold · 8 drag low · 9 upswing arc | heavy, hSweep, hOrder, ultVerdict |',
 "| b14 | 10 | 0–1 gavel forward · 2 long-handle extension · 3 gavel on a wavy cord still held · 4 back · 5–6 sword manifest / raise · 7 giant overhead · 8 sword thrust · 9 sword dive lunge | hPoke, hExt, ultOpen, ultVerdict, ultSword |",
 '', '## Actions (strip → source cells → timing)', '', '| action | use | frames (source cells) | loop | timing |', '|---|---|---|---|---|']
for k, cs in R['actions'].items():
    a = A.get(k, {}); t = T.get(k)
    tm = ('timeline ' + ', '.join(f'{x[0]}→{x[1]}' for x in t)) if t else f"{a.get('speed','?')} ticks / frame"
    L.append(f"| `{k}` | {USE.get(k, '')} | {len(cs)}: {' '.join(cs)} | {'yes' if a.get('loop') else 'no'} | {tm} |")
L += ['', '## Uncertainties and limits (art-honest)', '',
 '- **b02_0–1** read as a crouched step; used for walking back. Their original purpose is not labelled on the sheet.',
 '- **Thrown / recalled gavel (optional §8): NOT implemented.** b14_3 shows the gavel on a wavy cord that is still in his hand, i.e. a tethered extension,',
 '  not a detached projectile; there is no return / catch art. It is used as the Forward + Heavy Extended Lash, and L2 keeps the shared charge.',
 '- **J3** art is a spinning LOW sweep (b11_6–11), not a short finishing swing; it is used as the chain finisher, and the deviation is documented in MOVESET.md.',
 '- **Air normal** art (b10_5–6) is an upward swing, so its box sits above-forward rather than below.',
 '- Swing arcs merge into the gavel caps with no outline. Skin recolours separate metal from effect pixels by distance to the gavel wood (3 / 7 px); a few edge',
 '  pixels of an arc can take the metal colour (see SKINS.md).',
 '- There is no Judgeman, courtroom or opponent art on the sheet. The Deadly Sentencing courtroom is simple code-drawn rails, bench and floor marks, and nothing more is implied.',
 "- The sword cells (b14_5–9) are the only Executioner's Sword art; the sword is never generated or redrawn.", '']
open(f'{ROOT}/docs/higuruma/SPRITE_MAP.md', 'w').write('\n'.join(L))
print('wrote', len(L), 'lines;', len(cells), 'cells,', len([c for c in cells if c not in used]), 'unused')
